  sofia: [guide("Panorama", "Sofía tiene una comunidad queer pequeña, resiliente y conectada a cultura independiente y eventos."), guide("Barrios", "El centro es una base práctica para cafés, cena y desplazamientos cortos durante la noche."), guide("Seguridad", "Consulta información reciente sobre espacios y aplica precauciones urbanas sencillas al regresar tarde."), guide("Vida nocturna", "Una noche temática o un evento confirmado suele ser la puerta más clara a la escena local."), guide("Coste", "Alojamiento, comida y salidas pueden ser muy asequibles frente a otras capitales europeas.")],
  montevideo: [guide("Panorama", "Montevideo ofrece una vida queer tranquila, cultural y muy de barrio, con un ritmo amable junto al Río de la Plata."), guide("Barrios", "Ciudad Vieja, Cordón y Pocitos permiten elegir entre historia, bares, cena y costa."), guide("Seguridad", "La ciudad es manejable, pero organiza la vuelta y usa las precauciones habituales en zonas poco transitadas."), guide("Vida nocturna", "Bares, drag y eventos culturales dan una noche íntima que recompensa seguir la agenda local."), guide("Coste", "Puede resultar más caro que otras ciudades de la región, sobre todo en alojamiento y restaurantes.")],
  hamburg: [guide("Panorama", "Hamburgo suma puerto, música y una escena queer directa, diversa y muy conectada con la noche."), guide("Barrios", "St. Georg y St. Pauli sirven de anclas, con rutas diferentes para bares, cultura y clubs."), guide("Seguridad", "Muévete con la atención habitual de una gran ciudad y deja prevista la vuelta después de salir."), guide("Vida nocturna", "Drag, bares clásicos y noches de club dan muchas opciones si sigues el programa actual."), guide("Coste", "Los hoteles suben en fines de semana y ferias; una reserva temprana da mejor margen.")],
  munich: [guide("Panorama", "Múnich combina tradición bávara, diseño y una escena queer cuidada, sociable y bien organizada."), guide("Barrios", "Glockenbachviertel es el punto de partida natural para cena, bares y una noche caminable."), guide("Seguridad", "Es una ciudad fácil de leer; conserva las precauciones normales al final de una noche larga."), guide("Vida nocturna", "Bares, drag, clubs y fechas comunitarias permiten elegir un plan elegante o más intenso."), guide("Coste", "Es cara para Alemania, especialmente durante Oktoberfest, ferias y grandes fines de semana.")],
  frankfurt: [guide("Panorama", "Fráncfort ofrece una escena queer internacional, práctica y concentrada, acorde con su ritmo de ciudad global."), guide("Barrios", "El centro y áreas bien conectadas ayudan a unir cena, bares y regreso sin demasiada logística."), guide("Seguridad", "Mantén atención habitual en estaciones y zonas muy concurridas, especialmente de madrugada."), guide("Vida nocturna", "Eventos, drag y noches puntuales dan más personalidad que una búsqueda genérica de locales."), guide("Coste", "Alojamiento puede subir por congresos; mirar fechas antes de reservar es esencial.")],
  san_diego: [guide("Panorama", "San Diego mezcla sol, playa y una escena queer relajada, con una energía social fácil de disfrutar."), guide("Barrios", "Hillcrest es la referencia principal, mientras North Park suma restaurantes y planes de tarde."), guide("Seguridad", "La ciudad se recorre bien, pero las distancias hacen útil planear conductor, transporte o alojamiento cerca."), guide("Vida nocturna", "Bares, drag, brunch y eventos comunitarios dan un ritmo más amable que el de una gran metrópolis."), guide("Coste", "Hoteles y alquiler de coche pesan bastante; reservar con antelación ayuda mucho.")],
