  bratislava: [guide("Panorama", "Bratislava ofrece una escena queer pequeña, amable y fácil de combinar con cultura centroeuropea."), guide("Barrios", "El casco histórico y el centro son suficientes para una base compacta de cena y planes nocturnos."), guide("Seguridad", "La escala facilita la visita; aplica las precauciones habituales y confirma horarios de eventos."), guide("Vida nocturna", "Fiestas, colectivos y fechas puntuales aportan más que una larga lista de bares permanentes."), guide("Coste", "Suele ser una escapada accesible, especialmente comparada con capitales vecinas más grandes.")],
