const SPANISH_LANGUAGE_CITY_KEYS = new Set(["tenerife","puerto_vallarta","bogota","medellin","santiago","lima","quito","san_jose","guatemala_city","san_salvador","tegucigalpa","guadalajara","panama_city","caracas","asuncion","san_juan","cancun","havana","santo_domingo","managua","la_paz","cartagena","mendoza","bilbao","mallorca"]);

function spanishCityGuide(city) {
  const name = String(city || "").replaceAll("_", " ");
  return [guide("Panorama", `${name} ofrece una experiencia queer que conviene descubrir con contexto local, lugares verificados y una agenda actual.`), guide("Barrios", "Elige una base bien conectada y construye la ruta según el barrio, el día y el evento que realmente quieres vivir."), guide("Seguridad", "Consulta el contexto local antes de salir, mantén un regreso previsto y aplica las precauciones habituales de una noche urbana."), guide("Vida nocturna", "La mejor experiencia depende de la programación actual: combina una primera parada tranquila con un evento o local elegido con intención."), guide("Coste", "Reserva alojamiento con tiempo y deja margen para transporte, comidas y cambios de plan durante la noche.")];
}

export function getLocalizedCityGuide(city, locale, fallbackGuide = []) {
  if (String(locale || "").toLowerCase().split("-")[0] !== "es") return fallbackGuide;
  const key = String(city || "").toLowerCase();
  return SPANISH_CITY_GUIDES[key] || (SPANISH_LANGUAGE_CITY_KEYS.has(key) ? spanishCityGuide(key) : fallbackGuide);
}
